'use strict';
const chartMoney=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
function bidHistorySeries(rounds){let total=0;return [...rounds].sort((a,b)=>a.round-b.round).map(r=>({...r,increment:[6,7].includes(r.round)?0:r.total_bids,accumulated:total+=([6,7].includes(r.round)?0:r.total_bids)}))}
function drawBidHistory(rounds){
  const rows=bidHistorySeries(rounds),W=1000,H=420,left=75,right=25,top=48,bottom=315,max=Math.max(100000000,Math.ceil(Math.max(...rows.map(r=>r.accumulated))/100000000)*100000000),step=(W-left-right)/rows.length;
  const x=i=>left+step*(i+.5),y=v=>bottom-(bottom-top)*v/max,mi=v=>(v/1e6).toLocaleString('pt-BR',{maximumFractionDigits:1});
  let svg=`<svg class="bid-chart" viewBox="0 0 ${W} ${H}" role="group" aria-label="Lances por rodada e total acumulado, da primeira à oitava rodada"><title>Lances por rodada e total acumulado</title><desc>As barras mostram a contribuição de cada rodada. A linha mostra a soma da primeira rodada até a rodada indicada. Sexta e sétima têm contribuição zero porque não apresentam lances comparáveis, e não porque houve arrematação por zero reais.</desc><text x="${left}" y="24" class="axis-title">R$ milhões · mesma escala para barras e linha</text>`;
  for(let i=0;i<=5;i++){const v=max*i/5,yy=y(v);svg+=`<line x1="${left}" x2="${W-right}" y1="${yy}" y2="${yy}" class="chart-grid"/><text x="${left-12}" y="${yy+5}" text-anchor="end">${mi(v)}</text>`}
  rows.forEach((r,i)=>{const special=[6,7].includes(r.round),yy=y(r.increment);svg+=`<rect x="${x(i)-27}" y="${special?bottom-1:yy}" width="54" height="${special?2:Math.max(1,bottom-yy)}" fill="${special?'#69788a':'#1351b4'}"/><text x="${x(i)}" y="${Math.min(bottom-10,yy-10)}" text-anchor="middle" class="bar-label">${special?'0*':mi(r.increment)}</text><text x="${x(i)}" y="345" text-anchor="middle" class="round-label">${r.round}ª</text>${special?`<text x="${x(i)}" y="370" text-anchor="middle">${r.round===6?'Social':'Cancelada'}</text>`:''}`});
  svg+=`<polyline points="${rows.map((r,i)=>x(i)+','+y(r.accumulated)).join(' ')}" fill="none" stroke="#168821" stroke-width="3"/>`;
  rows.forEach((r,i)=>{svg+=`<circle cx="${x(i)}" cy="${y(r.accumulated)}" r="5" fill="#168821" stroke="white" stroke-width="2"/><g tabindex="0" role="button" class="chart-hit" data-chart-round="${r.round}" aria-label="${r.round}ª rodada: ${[6,7].includes(r.round)?'zero de acréscimo; lance não se aplica':chartMoney(r.increment)}; acumulado ${chartMoney(r.accumulated)}. Abrir áreas"><title>${r.round}ª rodada · incremento: ${chartMoney(r.increment)}${[6,7].includes(r.round)?' (não se aplica como lance)':''} · acumulado: ${chartMoney(r.accumulated)}</title><rect x="${left+i*step}" y="${top-20}" width="${step}" height="${H-top}" fill="transparent"/></g>`});
  svg+='</svg>';
  $('cumulative').innerHTML='<div class="chart-legend"><span><i class="legend-bar"></i>Lances da rodada</span><span><i class="legend-line"></i>Total acumulado até a rodada</span></div><div class="chart-scroll">'+svg+'</div><p class="caption" id="chart-reading" aria-live="polite">Passe o cursor ou use Tab para ler os valores. Clique em uma rodada para abrir suas áreas. * Zero de acréscimo na série financeira.</p><details><summary>Ver valores exatos em tabela</summary><div class="table-scroll"><table><thead><tr><th>Rodada</th><th>Acréscimo ao acumulado</th><th>Total acumulado</th><th>Contexto</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${r.round}ª</td><td>${chartMoney(r.increment)}${[6,7].includes(r.round)?'*':''}</td><td>${chartMoney(r.accumulated)}</td><td>${r.round===6?'Avaliação social · lance não se aplica':r.round===7?'Edital cancelado · lance não se aplica':'Lances vencedores registrados'}</td></tr>`).join('')+'</tbody></table></div></details>';
  $('cumulative').querySelectorAll('[data-chart-round]').forEach(el=>{const r=rows.find(r=>r.round===+el.dataset.chartRound),read=()=>{$('chart-reading').textContent=r.round+'ª rodada · '+([6,7].includes(r.round)?'R$ 0 de acréscimo; lance não se aplica':chartMoney(r.increment)+' em lances')+' · acumulado '+chartMoney(r.accumulated)};el.onfocus=read;el.onmouseenter=read;el.onclick=()=>openSelection(String(r.round));el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();openSelection(String(r.round))}}})
}
const fullButton=$('fullscreen-toggle');
function syncFullscreen(){const active=!!document.fullscreenElement||document.body.classList.contains('presentation-mode');fullButton.textContent=active?'Sair da tela cheia ⛶':'Tela cheia ⛶';fullButton.setAttribute('aria-pressed',String(active))}
fullButton.onclick=async()=>{if(document.fullscreenElement){await document.exitFullscreen();return}if(document.body.classList.contains('presentation-mode')){document.body.classList.remove('presentation-mode');syncFullscreen();return}try{if(!document.documentElement.requestFullscreen)throw Error('unsupported');await document.documentElement.requestFullscreen()}catch(e){document.body.classList.add('presentation-mode');$('status').textContent='Modo ampliado ativado nesta janela. Use Esc ou o botão para sair.'}syncFullscreen()};
document.addEventListener('fullscreenchange',syncFullscreen);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('presentation-mode')){document.body.classList.remove('presentation-mode');syncFullscreen()}});

